SourceCode.Declaration:
/// <summary>
/// controller class for Item state update batch job
/// </summary>
public class AVAItemStateUpdateController extends SysOperationServiceController
{
}

Method.Source:
protected void new()
{
    super();
    this.parmClassName(classStr(AVAItemStateUpdateService));
    this.parmMethodName(methodStr(AVAItemStateUpdateService, updateItemState));
    this.parmInBatch(true);
}

/// <summary>
/// Gets the description of the class.
/// </summary>
/// <returns>
/// The description of the class.
/// </returns>
public static ClassDescription description()
{
    return "@KAO479";
}

/// <summary>
/// construct method
/// </summary>
/// <param name = "_executionMode">SysOperationExecutionMode</param>
/// <returns>AVAItemStateUpdateController</returns>
public static AVAItemStateUpdateController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    AVAItemStateUpdateController controller;
    controller = new AVAItemStateUpdateController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

public static void main(Args _args)
{
    AVAItemStateUpdateController    controller;
    AVAItemStateUpdateContract      contract;

    if (!_args
        || _args.dataset() != tableNum(KCS_KAOItemStateTable))
    {
        throw error("@SYS25407");
    }

    controller = AVAItemStateUpdateController::construct();
    controller.parmArgs(_args);

    contract    = controller.getDataContractObject();
    contract.parmItemStateTable(_args.record());

    controller.startOperation();
}
